function visOpts(f) { return f.opts.filter(function (o) { return tierOk(o.tier || 0); }); }
function randOf(f, ids) { var pool = visOpts(f).filter(function (o) { return ids.indexOf(o.id) < 0; }); return pool.length ? pool[Math.floor(Math.random() * pool.length)] : null; }
/* 🎲 这一栏随机：单选＝换一个；多选＝再加一个没选过的 */
