  p.querySelectorAll('[data-fclr]').forEach(function (x) { x.addEventListener('click', function () { var f = this.getAttribute('data-fclr'); slotSet(curSlot, function (s) { s[f] = null; }); render(); }); });
  p.querySelectorAll('[data-rand]').forEach(function (x) { x.addEventListener('click', function () { randField(this.getAttribute('data-rand')); }); });
  p.querySelectorAll('[data-opt]').forEach(function (x) { x.addEventListener('click', function () { var v = this.getAttribute('data-opt').split('|'); pickOpt(v[0], v[1]); }); });
  p.querySelectorAll('[data-slotclr]').forEach(function (x) { x.addEventListener('click', function () { var n = +this.getAttribute('data-slotclr'); setSt(function (s) { if (s.custom && s.custom.slots) delete s.custom.slots[n]; }); syncCustom(); render(); }); });
  var who = p.querySelector('#' + NS + '-who');
